package server.bots;
import client.Character;import server.life.*;import java.awt.*;import java.util.List;import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class BotPinkBeanOuterFireTest {
 @Test void avoidanceReadsTheSharedNativeEffectBoxForAllMuninSeduceLevels(){var bird=mock(Monster.class);when(bird.getPosition()).thenReturn(new Point(5,-43));when(bird.getSkills()).thenReturn(java.util.Set.of(new MobSkillId(MobSkillType.SEDUCE,8),new MobSkillId(MobSkillType.SEDUCE,9),new MobSkillId(MobSkillType.SEDUCE,10)));var box=BotPinkBeanOuterFire.area(bird);assertEquals(new Rectangle(-795,-843,1600,1100),box);assertFalse(box.contains(new Point(840,-42)));assertFalse(box.contains(new Point(-830,-42)));assertTrue(box.contains(new Point(350,-456)));}
 @Test void aZombieBelowTheHealAreaDoesNotPreventHealingTheSeducedPartyOnThePlatform(){var b=mock(Character.class);var mate=mock(Character.class);var skill=mock(client.Skill.class);var effect=mock(server.StatEffect.class);when(b.getSkillLevel(constants.skills.Cleric.HEAL)).thenReturn(30);when(b.getPosition()).thenReturn(new Point(350,-456));when(b.getPartyMembersOnSameMap()).thenReturn(List.of(mate));when(mate.isAlive()).thenReturn(true);when(mate.hasDisease(client.Disease.ZOMBIFY)).thenReturn(true);when(mate.getPosition()).thenReturn(new Point(350,-42));when(skill.getEffect(30)).thenReturn(effect);when(effect.calculateBoundingBox(any(Point.class),anyBoolean())).thenReturn(new Rectangle(50,-656,600,400));try(var pink=mockStatic(BotPinkBeanRun.class,CALLS_REAL_METHODS);var factory=mockStatic(client.SkillFactory.class)){pink.when(()->BotPinkBeanRun.inInstance(b)).thenReturn(true);factory.when(()->client.SkillFactory.getSkill(constants.skills.Cleric.HEAL)).thenReturn(skill);assertTrue(BotPinkBeanRun.safeToHeal(b));when(mate.getPosition()).thenReturn(new Point(350,-456));assertFalse(BotPinkBeanRun.safeToHeal(b));}}
 @Test void nativeMaximumAddsOneSupportedPartyWithoutReplacingTheOriginalCrew(){assertEquals(29,BotPinkBeanRoster.JOBS.size());assertEquals(List.of(client.Job.BISHOP,client.Job.DARKKNIGHT,client.Job.BOWMASTER,client.Job.NIGHTLORD,client.Job.NIGHTLORD,client.Job.NIGHTLORD),BotPinkBeanRoster.JOBS.subList(23,29));for(int i=5;i<29;i+=6){var party=BotPinkBeanRoster.JOBS.subList(i,i+6);assertTrue(party.contains(client.Job.BISHOP));assertTrue(party.contains(client.Job.DARKKNIGHT));}}

 @Test void anUnprotectedRangedMemberWaitsSafelyForTheHyperBodyCasterInsteadOfChasingThroughAStatue(){
  var b=mock(Character.class,RETURNS_DEEP_STUBS);var provider=mock(Character.class);when(b.getBuffedValue(client.BuffStat.HYPERBODYHP)).thenReturn(null);when(b.getBuffedValue(client.BuffStat.HYPERBODYMP)).thenReturn(null);when(b.getJob()).thenReturn(client.Job.NIGHTLORD);when(b.isAlive()).thenReturn(true);when(b.getMapId()).thenReturn(270050100);when(b.getPosition()).thenReturn(new Point(350,-456));when(b.getPartyMembersOnSameMap()).thenReturn(List.of(b,provider));when(provider.isAlive()).thenReturn(true);when(provider.getSkillLevel(constants.skills.Spearman.HYPER_BODY)).thenReturn(30);var e=new BotEntry(b,b,null);
  try(var pink=mockStatic(BotPinkBeanRun.class);var combat=mockStatic(BotHorntailCombat.class);var hold=mockStatic(BotOpqRun.class);var move=mockStatic(BotPinkBeanMovement.class);var formation=mockStatic(BotPinkBeanFormation.class)){
   pink.when(()->BotPinkBeanRun.inInstance(b)).thenReturn(true);combat.when(()->BotHorntailCombat.safe(b,b.getPosition(),b.getMap().getAllMonsters())).thenReturn(true);hold.when(()->BotOpqRun.hold(e,b,true)).thenReturn(true);assertTrue(BotHorntailSupport.tick(e,b,List.of(b,provider),new java.util.HashSet<>(List.of("prepared-270050100")),b,"Pink Bean",true));move.verifyNoInteractions();hold.verify(()->BotOpqRun.hold(e,b,true));
   formation.when(()->BotPinkBeanFormation.required(b)).thenReturn(true);when(provider.getPosition()).thenReturn(new Point(350,-277));assertTrue(BotHorntailSupport.tick(e,b,List.of(b,provider),new java.util.HashSet<>(List.of("prepared-270050100")),b,"Pink Bean",true));move.verify(()->BotPinkBeanMovement.walkTo(e,b,provider.getPosition(),true));
  }
 }

 @Test void pinkRangedPreparationCoversRexsDispelGapWithoutChangingHorntailsFloor(){var pink=mock(Character.class);var horn=mock(Character.class);when(pink.getJob()).thenReturn(client.Job.NIGHTLORD);when(horn.getJob()).thenReturn(client.Job.NIGHTLORD);when(pink.getClient()).thenReturn(mock(client.BotClient.class));assertEquals(7500,BotRaidHp.minimumUnbuffed(horn));BotPinkBeanReadiness.mark(pink);assertEquals(8400,BotRaidHp.minimumUnbuffed(pink));assertEquals(7500,BotRaidHp.minimumUnbuffed(horn));}

 @Test void theCrewRalliesBeforeTheLastStatueCanAwakenMunin(){var b=mock(Character.class,RETURNS_DEEP_STUBS);when(b.getMap().getMonsterById(8820006)).thenReturn(null);var rex=mock(Monster.class);when(rex.isAlive()).thenReturn(true);when(rex.getId()).thenReturn(8820004);when(rex.getMaxHp()).thenReturn(300000000);when(rex.getHp()).thenReturn(75000000);when(b.getEventInstance().getIntProperty("stage")).thenReturn(3);when(b.getMap().getMonsterById(8820004)).thenReturn(rex);when(b.getMap().getAllMonsters()).thenReturn(List.of(rex));try(var pink=mockStatic(BotPinkBeanRun.class)){pink.when(()->BotPinkBeanRun.inInstance(b)).thenReturn(true);assertTrue(BotPinkBeanOuterFire.required(b));when(rex.getHp()).thenReturn(75000001);assertFalse(BotPinkBeanOuterFire.required(b));when(rex.getHp()).thenReturn(75000000);var other=mock(Monster.class);when(other.getId()).thenReturn(8820005);when(other.isAlive()).thenReturn(true);when(b.getMap().getAllMonsters()).thenReturn(List.of(rex,other));assertFalse(BotPinkBeanOuterFire.required(b));}}

 @Test void rallyDestinationsUseTheUpcomingWavePartyAssignments(){var b=mock(Character.class,RETURNS_DEEP_STUBS);when(b.getMap().getMonsterById(8820006)).thenReturn(null);var crew=new BotPinkBeanRun.Crew();when(b.getEventInstance().getIntProperty("stage")).thenReturn(4);try(var pink=mockStatic(BotPinkBeanRun.class);var physics=mockStatic(BotPhysicsEngine.class)){pink.when(()->BotPinkBeanRun.crew(b)).thenReturn(crew);physics.when(()->BotPhysicsEngine.findGroundPoint(eq(b.getMap()),any(Point.class))).thenAnswer(call->call.getArgument(1));pink.when(()->BotPinkBeanRun.partyIndex(crew,b)).thenReturn(1);assertEquals(new Point(840,-43),BotPinkBeanOuterFire.position(b));pink.when(()->BotPinkBeanRun.partyIndex(crew,b)).thenReturn(2);assertEquals(new Point(-830,-43),BotPinkBeanOuterFire.position(b));when(b.getEventInstance().getIntProperty("stage")).thenReturn(3);assertEquals(new Point(-830,-43),BotPinkBeanOuterFire.position(b));pink.when(()->BotPinkBeanRun.partyIndex(crew,b)).thenReturn(0);assertEquals(new Point(840,-43),BotPinkBeanOuterFire.position(b));}}
 @Test void aReturningRightPartyMemberSheltersOnItsCurrentSideOfTheNativeBox(){
  var b=mock(Character.class,RETURNS_DEEP_STUBS);var bird=mock(Monster.class);when(bird.getPosition()).thenReturn(new Point(5,-43));when(bird.getSkills()).thenReturn(java.util.Set.of(new MobSkillId(MobSkillType.SEDUCE,8)));when(b.getMap().getMonsterById(8820006)).thenReturn(bird);when(b.getEventInstance().getIntProperty("stage")).thenReturn(4);when(b.getPosition()).thenReturn(new Point(-801,-42));try(var physics=mockStatic(BotPhysicsEngine.class)){physics.when(()->BotPhysicsEngine.findGroundPoint(eq(b.getMap()),any(Point.class))).thenAnswer(call->call.getArgument(1));assertEquals(new Point(-830,-43),BotPinkBeanOuterFire.position(b));when(b.getPosition()).thenReturn(new Point(840,-42));assertEquals(new Point(840,-43),BotPinkBeanOuterFire.position(b));}
 }
 @Test void resurrectionDoesNotSendABishopAcrossMuninsActiveEffectBox(){
  var b=mock(Character.class);var fallen=mock(Character.class);var map=mock(server.maps.MapleMap.class);var party=mock(net.server.world.Party.class);when(b.getMap()).thenReturn(map);when(fallen.getMap()).thenReturn(map);when(b.getParty()).thenReturn(party);when(fallen.getParty()).thenReturn(party);when(b.getPosition()).thenReturn(new Point(840,-42));when(fallen.getPosition()).thenReturn(new Point(-830,-42));when(b.getSkillLevel(constants.skills.Bishop.RESURRECTION)).thenReturn(30);var bird=mock(Monster.class);when(bird.getPosition()).thenReturn(new Point(5,-43));when(bird.getSkills()).thenReturn(java.util.Set.of(new MobSkillId(MobSkillType.SEDUCE,8)));when(map.getMonsterById(8820006)).thenReturn(bird);var skill=mock(client.Skill.class);var effect=mock(server.StatEffect.class);when(skill.getEffect(30)).thenReturn(effect);when(effect.canPaySkillCost(b)).thenReturn(true);when(effect.calculateBoundingBox(b.getPosition(),false)).thenReturn(new Rectangle(540,-242,600,400));var entry=new BotEntry(b,b,null);
  try(var pink=mockStatic(BotPinkBeanRun.class);var skills=mockStatic(client.SkillFactory.class);var safe=mockStatic(BotHorntailCombat.class);var walk=mockStatic(BotPinkBeanMovement.class)){
   pink.when(()->BotPinkBeanRun.inInstance(b)).thenReturn(true);skills.when(()->client.SkillFactory.getSkill(constants.skills.Bishop.RESURRECTION)).thenReturn(skill);safe.when(()->BotHorntailCombat.safe(fallen,fallen.getPosition(),map.getAllMonsters())).thenReturn(true);assertFalse(BotHorntailRevive.tick(entry,b,List.of(b,fallen),true));walk.verifyNoInteractions();
  }
 }
 @Test void aMissingBotGetsRepeatedRallyRemindersWithOneSharedFifteenSecondTimer(){
  var b=mock(Character.class,RETURNS_DEEP_STUBS);var leader=mock(Character.class);
  when(b.getPosition()).thenReturn(new Point(840,-42));when(leader.getPosition()).thenReturn(new Point(641,-42));
  var map=b.getMap();when(leader.getMap()).thenReturn(map);when(b.isAlive()).thenReturn(true);when(leader.isAlive()).thenReturn(true);
  when(b.getEventInstance().getIntProperty("stage")).thenReturn(3);when(b.getMap().getMonsterById(8820006)).thenReturn(null);
  var crew=new BotPinkBeanRun.Crew();crew.leader=leader;crew.bots.add(b);crew.notices.add("outer-rally-guide-3");var e=new BotEntry(b,b,null);
  try(var outer=mockStatic(BotPinkBeanOuterFire.class,CALLS_REAL_METHODS);var pink=mockStatic(BotPinkBeanRun.class,CALLS_REAL_METHODS);var chat=mockStatic(BotPqChat.class);var hold=mockStatic(BotOpqRun.class)){
   outer.when(()->BotPinkBeanOuterFire.required(b)).thenReturn(true);
   outer.when(()->BotPinkBeanOuterFire.position(b)).thenReturn(new Point(840,-42));
   outer.when(()->BotPinkBeanOuterFire.position(leader)).thenReturn(new Point(840,-42));
   pink.when(()->BotPinkBeanRun.crew(b)).thenReturn(crew);
   long began=System.currentTimeMillis();BotPinkBeanOuterFire.tick(e,b,true);
   assertTrue(crew.next.get(-8820003)>=began+15000);chat.verifyNoInteractions();
   BotPinkBeanOuterFire.tick(e,b,true);chat.verifyNoInteractions();
   crew.next.put(-8820003,System.currentTimeMillis()-1);BotPinkBeanOuterFire.tick(e,b,true);
   chat.verify(()->BotPqChat.queue(eq(e),contains("We are regrouping the last bot crew members on their outer floor"),eq(false)),times(1));
   BotPinkBeanOuterFire.tick(e,b,true);
   chat.verify(()->BotPqChat.queue(eq(e),anyString(),eq(false)),times(1));
   crew.next.put(-8820003,System.currentTimeMillis()-1);BotPinkBeanOuterFire.tick(e,b,true);
   chat.verify(()->BotPqChat.queue(eq(e),anyString(),eq(false)),times(2));
  }
 }
}
